1	package ed2k
2	
3	import (
4		"context"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"sync"
10		"time"
11	
12		"github.com/GopeedLab/gopeed/internal/controller"
13		"github.com/GopeedLab/gopeed/internal/fetcher"
14		"github.com/GopeedLab/gopeed/pkg/base"
15		ped2k "github.com/GopeedLab/gopeed/pkg/protocol/ed2k"
16		"github.com/monkeyWie/goed2k"
17		gprotocol "github.com/monkeyWie/goed2k/protocol"
18	)
19	
20	type clientStateStore struct {
21		store fetcher.ProtocolStateStore
22	}
23	
24	func (s *clientStateStore) Load() (*goed2k.ClientState, error) {
25		if s == nil || s.store == nil {
26			return nil, nil
27		}
28		var state goed2k.ClientState
29		exist, err := s.store.Load(&state)
30		if err != nil {
31			return nil, err
32		}
33		if !exist {
34			return nil, nil
35		}
36		return &state, nil
37	}
38	
39	func (s *clientStateStore) Save(state *goed2k.ClientState) error {
40		if s == nil || s.store == nil {
41			return nil
42		}
43		if state == nil {
44			return s.store.Delete()
45		}
46		return s.store.Save(state)
47	}
48	
49	type Fetcher struct {
50		ctl    *controller.Controller
51		config *config
52	
53		manager *FetcherManager
54		meta    *fetcher.FetcherMeta
55		handle  goed2k.TransferHandle
56	
57		waitCtx    context.Context
58		waitCancel context.CancelFunc
59	}
60	
61	func (f *Fetcher) Setup(ctl *controller.Controller) {
62		f.ctl = ctl
63		if f.meta == nil {
64			f.meta = &fetcher.FetcherMeta{}
65		}
66		f.waitCtx, f.waitCancel = context.WithCancel(context.Background())
67		f.ctl.GetConfig(&f.config)
68	}
69	
70	func (f *Fetcher) Resolve(req *base.Request) error {
71		link, err := parseLink(req.URL)
72		if err != nil {
73			return err
74		}
75	
76		f.meta.Req = req
77	
78		f.meta.Res = buildResource(link)
79		return nil
80	}
81	
82	func (f *Fetcher) Start() error {
83		link, err := parseLink(f.meta.Req.URL)
84		if err != nil {
85			return err
86		}
87		if f.meta.Res == nil {
88			f.meta.Res = buildResource(link)
89		}
90	
91		client, err := f.getClient()
92		if err != nil {
93			return err
94		}
95	
96		targetPath := f.meta.SingleFilepath()
97		if err := os.MkdirAll(filepath.Dir(targetPath), 0o755); err != nil {
98			return err
99		}
100	
101		handle := client.FindTransfer(link.Hash)
102		if handle.IsValid() {
103			f.handle = handle
104			if handle.IsPaused() {
105				if err := client.ResumeTransfer(handle.GetHash()); err != nil {
106					return err
107				}
108			}
109			return nil
110		}
111	
112		atp := goed2k.AddTransferParams{
113			Hash:       link.Hash,
114			CreateTime: time.Now().UnixMilli(),
115			Size:       link.NumberValue,
116			FilePath:   targetPath,
117		}
118		handle, err = client.AddTransfer(atp)
119		if err != nil {
120			return err
121		}
122		f.handle = handle
123		if handle.IsValid() && handle.IsPaused() {
124			if err := client.ResumeTransfer(handle.GetHash()); err != nil {
125				return err
126			}
127		}
128		return nil
129	}
130	
131	func (f *Fetcher) Patch(req *base.Request, opts *base.Options) error {
132		handle := f.currentHandle()
133	
134		if opts != nil && (opts.Name != "" || opts.Path != "") && handle.IsValid() {
135			return errors.New("cannot change ed2k target path after transfer started")
136		}
137		if req != nil && req.URL != "" && handle.IsValid() {
138			return errors.New("cannot change ed2k link after transfer started")
139		}
140	
141		if req != nil {
142			if req.URL != "" {
143				link, err := parseLink(req.URL)
144				if err != nil {
145					return err
146				}
147				f.meta.Req.URL = req.URL
148				f.meta.Res = buildResource(link)
149			}
150			if req.Labels != nil {
151				if f.meta.Req.Labels == nil {
152					f.meta.Req.Labels = make(map[string]string)
153				}
154				for k, v := range req.Labels {
155					f.meta.Req.Labels[k] = v
156				}
157			}
158			if req.Proxy != nil {
159				f.meta.Req.Proxy = req.Proxy
160			}
161		}
162	
163		if opts != nil {
164			if opts.Name != "" {
165				f.meta.Opts.Name = opts.Name
166			}
167			if opts.Path != "" {
168				f.meta.Opts.Path = opts.Path
169			}
170		}
171		return nil
172	}
173	
174	func (f *Fetcher) Pause() error {
175		handle := f.currentHandle()
176		if !handle.IsValid() {
177			return nil
178		}
179		client, err := f.getClient()
180		if err != nil {
181			return err
182		}
183		if err := client.PauseTransfer(handle.GetHash()); err != nil {
184			return err
185		}
186		f.handle = handle
187		return nil
188	}
189	
190	func (f *Fetcher) Close() error {
191		if f.waitCancel != nil {
192			f.waitCancel()
193		}
194		handle := f.currentHandle()
195		if !handle.IsValid() {
196			return nil
197		}
198		client, err := f.getClient()
199		if err != nil {
200			return err
201		}
202		f.handle = handle
203		return client.RemoveTransfer(handle.GetHash(), false)
204	}
205	
206	func (f *Fetcher) Meta() *fetcher.FetcherMeta {
207		return f.meta
208	}
209	
210	func (f *Fetcher) Stats() *fetcher.Stats {
211		handle := f.currentHandle()
212		if !handle.IsValid() {
213			return &fetcher.Stats{
214				Runtime: &ped2k.StatsRuntime{
215					Peers: make([]*base.PeerStats, 0),
216				},
217			}
218		}
219		status := handle.GetStatus()
220		pieceMap := buildED2KPieceMap(handle.PieceSnapshots())
221		mapReady := pieceMap != nil && status.State != goed2k.LoadingResumeData && status.State != goed2k.Verifying
222		var snapshot any
223		if mapReady {
224			snapshot = &ped2k.StatsSnapshot{
225				Upload:        status.Upload,
226				TotalDone:     status.TotalDone,
227				TotalReceived: status.TotalReceived,
228				TotalWanted:   status.TotalWanted,
229				PieceMap:      pieceMap.Clone(),
230			}
231		}
232		// Resume loading and verification are transitional. A nil Snapshot retains
233		// the last trusted completion bitset until goed2k publishes a stable map.
234		return &fetcher.Stats{
235			Snapshot: snapshot,
236			Runtime: &ped2k.StatsRuntime{
237				State:        string(status.State),
238				Paused:       status.Paused,
239				ActivePeers:  handle.ActiveConnections(),
240				TotalPeers:   status.NumPeers,
241				DownloadRate: status.DownloadRate,
242				UploadRate:   status.UploadRate,
243				Peers:        buildED2KPeers(handle.GetPeersInfo()),
244			},
245		}
246	}
247	
248	func buildED2KPieceMap(snapshots []goed2k.PieceSnapshot) *base.PieceMap {
249		if len(snapshots) == 0 {
250			return nil
251		}
252		pieceMap := base.NewPieceMap(len(snapshots), goed2k.PieceSize)
253		for _, snapshot := range snapshots {
254			if snapshot.Index < 0 || snapshot.Index >= pieceMap.PieceCount() {
255				continue
256			}
257			_ = pieceMap.Update(snapshot.Index, snapshot.State == goed2k.PieceSnapshotFinished)
258		}
259		return pieceMap
260	}
261	
262	func buildED2KPeers(peerInfos []goed2k.PeerInfo) []*base.PeerStats {
263		peers := make([]*base.PeerStats, 0, len(peerInfos))
264		for _, peerInfo := range peerInfos {
265			peers = append(peers, &base.PeerStats{
266				Address:       peerInfo.Endpoint.String(),
267				Client:        ed2kPeerClient(peerInfo),
268				DownloadSpeed: int64(peerInfo.PayloadDownloadSpeed),
269				UploadSpeed:   int64(peerInfo.PayloadUploadSpeed),
270				PieceCount:    peerInfo.RemotePieces.Count(),
271				Source:        peerInfo.SourceString(),
272				Transport:     "tcp",
273			})
274		}
275		return peers
276	}
277	
278	func ed2kPeerClient(peerInfo goed2k.PeerInfo) string {
279		return strings.TrimSpace(peerInfo.ModName + " " + peerInfo.StrModVersion)
280	}
281	
282	func (f *Fetcher) Progress() fetcher.Progress {
283		handle := f.currentHandle()
284		if !handle.IsValid() {
285			return fetcher.Progress{0}
286		}
287		return fetcher.Progress{handle.GetStatus().TotalReceived}
288	}
289	
290	func (f *Fetcher) Wait() error {
291		client, err := f.getClient()
292		if err != nil {
293			return err
294		}
295	
296		hash, err := f.hash()
297		if err != nil {
298			return err
299		}
300	
301		handle := f.currentHandle()
302		if handle.IsValid() && handle.IsFinished() {
303			return nil
304		}
305	
306		progressCh, cancel := client.SubscribeTransferProgress()
307		defer cancel()
308	
309		for {
310			select {
311			case <-f.waitCtx.Done():
312				return nil
313			case event, ok := <-progressCh:
314				if !ok {
315					return nil
316				}
317				for _, transfer := range event.Transfers {
318					if transfer.Hash.Compare(hash) != 0 {
319						continue
320					}
321					// Removal can happen during task deletion or client shutdown, both of
322					// which should unblock Wait without treating it as a download failure.
323					if transfer.Removed || transfer.State == goed2k.Finished {
324						return nil
325					}
326				}
327			}
328		}
329	}
330	
331	func (f *Fetcher) getClient() (*goed2k.Client, error) {
332		if f.manager == nil {
333			f.manager = &FetcherManager{}
334		}
335		return f.manager.initClient(f.config)
336	}
337	
338	func (f *Fetcher) currentHandle() goed2k.TransferHandle {
339		if f.handle.IsValid() {
340			return f.handle
341		}
342		if f.manager == nil {
343			return f.handle
344		}
345		client := f.manager.currentClient()
346		if client == nil {
347			return f.handle
348		}
349		hash, err := f.hash()
350		if err != nil {
351			return f.handle
352		}
353		handle := client.FindTransfer(hash)
354		if handle.IsValid() {
355			f.handle = handle
356		}
357		return f.handle
358	}
359	
360	func (f *Fetcher) hash() (gprotocol.Hash, error) {
361		if f.meta == nil || f.meta.Req == nil {
362			return gprotocol.Invalid, errors.New("ed2k link is empty")
363		}
364		link, err := parseLink(f.meta.Req.URL)
365		if err != nil {
366			return gprotocol.Invalid, err
367		}
368		return link.Hash, nil
369	}
370	
371	type FetcherManager struct {
372		mu         sync.Mutex
373		client     *goed2k.Client
374		stateStore *clientStateStore
375	}
376	
377	func (fm *FetcherManager) SetStateStore(store fetcher.ProtocolStateStore) {
378		fm.mu.Lock()
379		defer fm.mu.Unlock()
380	
381		if fm.stateStore == nil {
382			fm.stateStore = &clientStateStore{}
383		}
384		fm.stateStore.store = store
385		if fm.client != nil {
386			fm.client.SetStateStore(fm.stateStore)
387		}
388	}
389	
390	func (fm *FetcherManager) Name() string {
391		return "ed2k"
392	}
393	
394	func (fm *FetcherManager) Filters() []*fetcher.SchemeFilter {
395		return []*fetcher.SchemeFilter{
396			{
397				Type:    fetcher.FilterTypeUrl,
398				Pattern: "ED2K",
399			},
400		}
401	}
402	
403	func (fm *FetcherManager) Build() fetcher.Fetcher {
404		return &Fetcher{manager: fm}
405	}
406	
407	func (fm *FetcherManager) ParseName(u string) string {
408		link, err := parseLink(u)
409		if err != nil {
410			return ""
411		}
412		return link.StringValue
413	}
414	
415	func (fm *FetcherManager) AutoRename() bool {
416		return true
417	}
418	
419	func (fm *FetcherManager) DefaultConfig() any {
420		return &config{
421			ListenPort: 0,
422			UDPPort:    0,
423			ServerAddr: defaultServerList,
424			ServerMet:  defaultServerMet,
425			NodesDat:   defaultNodesDat,
426		}
427	}
428	
429	func (fm *FetcherManager) Store(f fetcher.Fetcher) (any, error) {
430		return nil, nil
431	}
432	
433	func (fm *FetcherManager) Restore() (v any, f func(meta *fetcher.FetcherMeta, v any) fetcher.Fetcher) {
434		return nil, func(meta *fetcher.FetcherMeta, v any) fetcher.Fetcher {
435			return &Fetcher{
436				manager: fm,
437				meta:    meta,
438			}
439		}
440	}
441	
442	func (fm *FetcherManager) Close() error {
443		fm.mu.Lock()
444		defer fm.mu.Unlock()
445	
446		if fm.client != nil {
447			fm.client.Close()
448			fm.client = nil
449		}
450		return nil
451	}
452	
453	func parseLink(raw string) (goed2k.EMuleLink, error) {
454		link, err := goed2k.ParseEMuleLink(raw)
455		if err != nil {
456			return goed2k.EMuleLink{}, err
457		}
458		if link.Type != goed2k.LinkFile {
459			return goed2k.EMuleLink{}, errors.New("unsupported ed2k link type")
460		}
461		return link, nil
462	}
463	
464	func buildResource(link goed2k.EMuleLink) *base.Resource {
465		return &base.Resource{
466			Size:  link.NumberValue,
467			Range: false,
468			Hash:  link.Hash.String(),
469			Files: []*base.FileInfo{
470				{
471					Name: link.StringValue,
472					Size: link.NumberValue,
473				},
474			},
475		}
476	}
477	
478	func splitCommaList(value string) []string {
479		if strings.TrimSpace(value) == "" {
480			return nil
481		}
482		parts := strings.Split(value, ",")
483		out := make([]string, 0, len(parts))
484		for _, part := range parts {
485			part = strings.TrimSpace(part)
486			if part != "" {
487				out = append(out, part)
488			}
489		}
490		return out
491	}
492	
493	func (fm *FetcherManager) getStateStoreLocked() *clientStateStore {
494		if fm.stateStore == nil {
495			fm.stateStore = &clientStateStore{}
496		}
497		return fm.stateStore
498	}
499	
500	func (fm *FetcherManager) currentClient() *goed2k.Client {
501		fm.mu.Lock()
502		defer fm.mu.Unlock()
503		return fm.client
504	}
505	
506	func (fm *FetcherManager) initClient(cfg *config) (*goed2k.Client, error) {
507		fm.mu.Lock()
508		defer fm.mu.Unlock()
509	
510		if fm.client != nil {
511			return fm.client, nil
512		}
513		if cfg == nil {
514			cfg = fm.DefaultConfig().(*config)
515		}
516	
517		settings := goed2k.NewSettings()
518		settings.ListenPort = cfg.ListenPort
519		settings.UDPPort = cfg.UDPPort
520		settings.EnableDHT = true
521		settings.EnableUPnP = true
522		settings.ReconnectToServer = true
523	
524		client := goed2k.NewClient(settings)
525		client.SetStateStore(fm.getStateStoreLocked())
526		if err := client.LoadState(""); err != nil {
527			return nil, err
528		}
529		if err := client.Start(); err != nil {
530			return nil, err
531		}
532		fm.client = client
533		// Bootstrap is best-effort: downloads can still proceed later even if
534		// server list or DHT initialization fails during startup.
535		bootstrapClient(client, cfg)
536		return fm.client, nil
537	}
538	
539	func bootstrapClient(client *goed2k.Client, cfg *config) {
540		for _, serverAddr := range splitCommaList(cfg.ServerAddr) {
541			go func(serverAddr string) {
542				_ = client.Connect(serverAddr)
543			}(serverAddr)
544		}
545		for _, source := range splitCommaList(cfg.ServerMet) {
546			go func(source string) {
547				_ = client.ConnectServerMet(source)
548			}(source)
549		}
550		if cfg.NodesDat != "" {
551			go func() {
552				_ = client.LoadDHTNodesDat(cfg.NodesDat)
553			}()
554		}
555	}
556

