262	func buildED2KPeers(peerInfos []goed2k.PeerInfo) []*base.PeerStats {
263		peers := make([]*base.PeerStats, 0, len(peerInfos))
264		for _, peerInfo := range peerInfos {
265			peers = append(peers, &base.PeerStats{
266				Address:       peerInfo.Endpoint.String(),
267				Client:        ed2kPeerClient(peerInfo),
268				DownloadSpeed: int64(peerInfo.PayloadDownloadSpeed),
269				UploadSpeed:   int64(peerInfo.PayloadUploadSpeed),
270				PieceCount:    peerInfo.RemotePieces.Count(),
271				Source:        peerInfo.SourceString(),
272				Transport:     "tcp",
273			})
274		}
275		return peers
276	}
277	
278	func ed2kPeerClient(peerInfo goed2k.PeerInfo) string {
279		return strings.TrimSpace(peerInfo.ModName + " " + peerInfo.StrModVersion)
280	}
281	
282	func (f *Fetcher) Progress() fetcher.Progress {
283		handle := f.currentHandle()
284		if !handle.IsValid() {
285			return fetcher.Progress{0}
286		}
287		return fetcher.Progress{handle.GetStatus().TotalReceived}
288	}
289	
290	func (f *Fetcher) Wait() error {
291		client, err := f.getClient()
292		if err != nil {
293			return err
294		}
295	
296		hash, err := f.hash()
297		if err != nil {
298			return err
299		}
300	
301		handle := f.currentHandle()
302		if handle.IsValid() && handle.IsFinished() {
303			return nil
304		}
305	
306		progressCh, cancel := client.SubscribeTransferProgress()
307		defer cancel()
308	
309		for {
310			select {
311			case <-f.waitCtx.Done():
312				return nil
313			case event, ok := <-progressCh:
314				if !ok {
315					return nil
316				}
317				for _, transfer := range event.Transfers {
318					if transfer.Hash.Compare(hash) != 0 {
319						continue
320					}
321					// Removal can happen during task deletion or client shutdown, both of
322					// which should unblock Wait without treating it as a download failure.
323					if transfer.Removed || transfer.State == goed2k.Finished {
324						return nil
325					}
326				}
327			}
328		}
329	}
330	
331	func (f *Fetcher) getClient() (*goed2k.Client, error) {
332		if f.manager == nil {
333			f.manager = &FetcherManager{}
334		}
335		return f.manager.initClient(f.config)
336	}
337	
338	func (f *Fetcher) currentHandle() goed2k.TransferHandle {
339		if f.handle.IsValid() {
340			return f.handle
341		}
342		if f.manager == nil {
343			return f.handle
344		}
345		client := f.manager.currentClient()
346		if client == nil {
347			return f.handle
348		}
349		hash, err := f.hash()
350		if err != nil {
351			return f.handle
352		}
353		handle := client.FindTransfer(hash)
354		if handle.IsValid() {
355			f.handle = handle
356		}
357		return f.handle
358	}
359	
360	func (f *Fetcher) hash() (gprotocol.Hash, error) {
361		if f.meta == nil || f.meta.Req == nil {
362			return gprotocol.Invalid, errors.New("ed2k link is empty")
363		}
364		link, err := parseLink(f.meta.Req.URL)
365		if err != nil {
366			return gprotocol.Invalid, err
367		}
368		return link.Hash, nil
369	}
