377	func (fm *FetcherManager) SetStateStore(store fetcher.ProtocolStateStore) {
378		fm.mu.Lock()
379		defer fm.mu.Unlock()
380	
381		if fm.stateStore == nil {
382			fm.stateStore = &clientStateStore{}
383		}
384		fm.stateStore.store = store
385		if fm.client != nil {
386			fm.client.SetStateStore(fm.stateStore)
387		}
388	}
