442	func (fm *FetcherManager) Close() error {
443		fm.mu.Lock()
444		defer fm.mu.Unlock()
445	
446		if fm.client != nil {
447			fm.client.Close()
448			fm.client = nil
449		}
450		return nil
451	}
452	
453	func parseLink(raw string) (goed2k.EMuleLink, error) {
454		link, err := goed2k.ParseEMuleLink(raw)
455		if err != nil {
456			return goed2k.EMuleLink{}, err
457		}
458		if link.Type != goed2k.LinkFile {
459			return goed2k.EMuleLink{}, errors.New("unsupported ed2k link type")
460		}
461		return link, nil
462	}
463	
464	func buildResource(link goed2k.EMuleLink) *base.Resource {
465		return &base.Resource{
466			Size:  link.NumberValue,
467			Range: false,
468			Hash:  link.Hash.String(),
469			Files: []*base.FileInfo{
470				{
471					Name: link.StringValue,
472					Size: link.NumberValue,
473				},
474			},
475		}
476	}
477	
478	func splitCommaList(value string) []string {
479		if strings.TrimSpace(value) == "" {
480			return nil
481		}
482		parts := strings.Split(value, ",")
483		out := make([]string, 0, len(parts))
484		for _, part := range parts {
485			part = strings.TrimSpace(part)
486			if part != "" {
487				out = append(out, part)
488			}
489		}
490		return out
491	}
492	
493	func (fm *FetcherManager) getStateStoreLocked() *clientStateStore {
494		if fm.stateStore == nil {
495			fm.stateStore = &clientStateStore{}
496		}
497		return fm.stateStore
498	}
499	
500	func (fm *FetcherManager) currentClient() *goed2k.Client {
501		fm.mu.Lock()
502		defer fm.mu.Unlock()
503		return fm.client
504	}
505	
506	func (fm *FetcherManager) initClient(cfg *config) (*goed2k.Client, error) {
507		fm.mu.Lock()
508		defer fm.mu.Unlock()
509	
510		if fm.client != nil {
511			return fm.client, nil
512		}
513		if cfg == nil {
514			cfg = fm.DefaultConfig().(*config)
515		}
516	
517		settings := goed2k.NewSettings()
518		settings.ListenPort = cfg.ListenPort
519		settings.UDPPort = cfg.UDPPort
520		settings.EnableDHT = true
521		settings.EnableUPnP = true
522		settings.ReconnectToServer = true
523	
524		client := goed2k.NewClient(settings)
525		client.SetStateStore(fm.getStateStoreLocked())
526		if err := client.LoadState(""); err != nil {
527			return nil, err
528		}
529		if err := client.Start(); err != nil {
530			return nil, err
531		}
532		fm.client = client
533		// Bootstrap is best-effort: downloads can still proceed later even if
534		// server list or DHT initialization fails during startup.
535		bootstrapClient(client, cfg)
536		return fm.client, nil
537	}
538	
539	func bootstrapClient(client *goed2k.Client, cfg *config) {
540		for _, serverAddr := range splitCommaList(cfg.ServerAddr) {
541			go func(serverAddr string) {
542				_ = client.Connect(serverAddr)
543			}(serverAddr)
544		}
545		for _, source := range splitCommaList(cfg.ServerMet) {
546			go func(source string) {
547				_ = client.ConnectServerMet(source)
548			}(source)
549		}
550		if cfg.NodesDat != "" {
551			go func() {
552				_ = client.LoadDHTNodesDat(cfg.NodesDat)
553			}()
554		}
555	}
