	valueDefault := reflect.TypeOf(target).Kind() != reflect.Pointer
	if valueDefault {
		pointer := reflect.New(reflect.TypeOf(target))
		defaults, err := json.Marshal(target)
		if err != nil {
			return nil, err
		}
		if err = json.Unmarshal(defaults, pointer.Interface()); err != nil {
			return nil, err
